const moodOptions=[['comfort','우울할 때'],['energy','기분 업'],['focus','집중'],['drive','드라이브'],['sleep','잠들기 전'],['workout','운동']];
let collectionSearch='',collectionSort='custom',collectionFilter='all';
const isSavedPlaylist=id=>(library.saved||[]).some(p=>p.id===id);
function playlistArt(p,cls='collection-art'){const covers=p.covers||[];return `<div class="${cls} collage collage-${Math.min(covers.length,4)}">${covers.length?covers.map(t=>cover(t,'collection-tile')).join(''):`<span>${icon('list')}</span>`}</div>`;}
function collectionCard(p){const owned=me?.id===p.user_id,inLibrary=owned||p.saved;return `<article class="collection-card ${p.locked?'collection-locked':''}"><a href="#playlist/${p.id}" class="collection-main">${playlistArt(p)}<span class="collection-kind">${p.pinned?'고정 · ':''}${owned?'내 플레이리스트':esc(p.owner_name||'리스너')+'의 선곡'}</span><h2>${p.locked?'<small class="locked-badge">보관 중</small>':''}${esc(p.name)}</h2><p>${esc(p.description||'좋아하는 음악을 모은 플레이리스트')}</p><small>${p.tracks}곡 · ${time(p.duration)} · ${p.is_public?'공개':'비공개'}</small></a><div class="collection-card-actions">${inLibrary?`<button class="text-link ${p.pinned?'is-active':''}" data-pin-collection="${p.id}" data-pinned="${!!p.pinned}" aria-pressed="${!!p.pinned}">${p.pinned?'고정 해제':'상단 고정'}</button>`:`<button class="text-link" data-save-collection="${p.id}" data-saved="false">${icon('plus')} 보관함 저장</button>`}<a href="#playlist/${p.id}" aria-label="${esc(p.name)} 열기">열기 →</a></div></article>`;}
function collectionGrid(items,message='아직 플레이리스트가 없어요'){return items.length?`<div class="collection-grid">${items.map(collectionCard).join('')}</div>`:empty(message,'좋아하는 음악을 모아 나만의 플레이리스트를 만들어보세요.','#library/playlists','내 보관함');}
function discoveryTabs(active){return `<div class="tabs explorer-tabs">${[['','추천'],['themes','기분·활동'],['genres','장르'],['following','팔로잉 신곡']].map(([id,label])=>`<a class="tab ${active===id?'active':''}" href="#discover${id?'/'+id:''}">${label}</a>`).join('')}<a class="tab" href="#collections">공개 플레이리스트</a></div>`;}
function moodCards(moods,selected=''){return `<div class="mood-grid">${moods.map((m,i)=>`<a class="mood-card mood-${i} ${selected===m.id?'selected':''}" href="#discover/mood?m=${m.id}" ${selected===m.id?'aria-current="page"':''}><span aria-hidden="true">${m.symbol}</span><strong>${esc(m.name)}</strong><small>${esc(m.caption)}</small><em>${m.count}곡</em></a>`).join('')}</div>`;}
async function explorerView(base,param,raw){
 const params=new URLSearchParams(raw.split('?')[1]||'');
 if(base==='membership'){if(me)await refreshLibrary();let billing;try{billing=await api('/api/billing/status');}catch{}return {html:membershipHTML(billing)};}
 if(base==='discover'){
  const active=param==='mood'?'themes':genres.includes(decodeURIComponent(param||''))?'genres':param||'',mood=params.get('m')||'',genre=params.get('g')||(genres.includes(decodeURIComponent(param||''))?decodeURIComponent(param):'전체');
  if(active==='following'&&!me){returnRoute=location.hash;return {html:heading('팔로잉 신곡','좋아하는 창작자의 새 음악을 만나보세요.')+discoveryTabs(active)+gate()};}
  const query=new URLSearchParams();if(param==='mood'&&mood)query.set('mood',mood);if(active==='genres'&&genre!=='전체')query.set('genre',genre);if(active==='following')query.set('following','1');
  const d=await api('/api/discovery?'+query),selected=d.moods.find(x=>x.id===mood);
  let html=heading('음악 발견','오늘의 기분에서, 다음 취향까지.')+discoveryTabs(active);
  if(active===''||active==='themes')html+=moodCards(d.moods,selected?.id);
  if(active==='genres')html+=`<div class="genre-chips">${genres.map(g=>`<a class="genre-chip ${g===genre?'active':''}" href="#discover/genres?g=${encodeURIComponent(g)}">${g}</a>`).join('')}</div>`;
  html+=section(selected?selected.name+'에 듣는 음악':active==='following'?'팔로우한 창작자의 새 음악':active==='genres'?genre+' 음악':'지금 만나는 음악');
  html+=`<p class="field-help">${selected?'제작자가 등록한 분위기 태그로 모았어요.':active==='following'?'팔로우한 AI 아티스트와 제작자의 곡을 최신순으로 보여드려요.':'공개된 음악의 감상·좋아요와 등록 시점을 바탕으로 보여드려요.'}</p>`;
  html+=d.tracks.length?grid(d.tracks):empty(selected?'이 분위기의 음악을 기다리고 있어요.':active==='following'?'팔로우한 창작자의 음악이 아직 없어요.':'등록된 음악이 아직 없어요.','다른 음악과 새로운 창작자를 만나보세요.',active==='following'?'#artists':'#discover/genres',active==='following'?'아티스트 둘러보기':'다른 장르 둘러보기');
  if(active===''){const p=await api('/api/playlists?sort=popular');html+=section('함께 나누는 플레이리스트','#collections')+collectionGrid(p.playlists.slice(0,4),'첫 공개 플레이리스트를 만들어보세요.');}
  return {html,tracks:d.tracks};
 }
 if(base==='collections'){
  const q=params.get('q')||'',sort=params.get('sort')==='recent'?'recent':'popular',d=await api('/api/playlists?'+new URLSearchParams({q,sort}));
  return {html:heading('공개 플레이리스트','다른 사람의 취향에서 새로운 음악을 발견하세요.')+`<form id="collection-search" class="explorer-toolbar"><input name="q" aria-label="공개 플레이리스트 검색" placeholder="제목, 소개, 만든 사람 검색" value="${esc(q)}" maxlength="100"><select name="sort" aria-label="공개 플레이리스트 정렬"><option value="popular" ${sort==='popular'?'selected':''}>많이 저장한 순</option><option value="recent" ${sort==='recent'?'selected':''}>최신순</option></select><button class="primary-button">검색</button></form><p class="field-help">공개 목록을 저장하면 만든 사람이 추가한 곡도 함께 반영됩니다.</p>`+collectionGrid(d.playlists,q?'검색 결과가 없어요.':'아직 공개된 플레이리스트가 없어요.')};
 }
 if(base==='search'){
  const q=decodeURIComponent(param||''),tab=['tracks','artists','producers','playlists'].includes(params.get('type'))?params.get('type'):'tracks',d=await api('/api/search?q='+encodeURIComponent(q));
  let html=heading('음악 검색','음악과 창작자, 취향이 담긴 플레이리스트까지.')+`<form id="search-form" class="aifect-search">${icon('search')}<input name="q" aria-label="곡, 아티스트, 제작자 검색" placeholder="곡, 아티스트, 제작자, 플레이리스트" value="${esc(q)}" maxlength="100"><button class="primary-button">검색</button></form><div class="tabs">${[['tracks','곡'],['artists','AI 아티스트'],['producers','제작자'],['playlists','플레이리스트']].map(([k,v])=>`<a class="tab ${tab===k?'active':''}" href="#search/${encodeURIComponent(q)}?type=${k}">${v} <span>${d[k].length}</span></a>`).join('')}</div>`;
  html+=!q?empty('어떤 음악을 찾고 계신가요?','제목이나 창작자 이름을 검색해보세요.','#discover','음악 발견하기'):!d[tab].length?empty('검색 결과가 없어요.','다른 검색어나 결과 탭을 선택해보세요.','#discover','음악 발견하기'):tab==='tracks'?list(d.tracks):tab==='playlists'?collectionGrid(d.playlists):identityCards(d[tab],tab==='artists'?'artist':'producer');return {html,tracks:d.tracks};
 }
 if(base==='library'){
  if(!me){returnRoute=location.hash;return {html:gate()};}await refreshLibrary();const tab=param||'likes';
  let html=heading('내 보관함','좋아하는 음악을 모으고, 오늘의 기분대로 들어보세요.')+`<div class="tabs">${[['likes','좋아요'],['playlists','플레이리스트'],['artists','아티스트'],['producers','제작자']].map(([k,v])=>`<a class="tab ${tab===k?'active':''}" href="#library/${k}">${v}</a>`).join('')}</div>`;
  if(tab==='playlists')html+=playlistQuotaHTML()+`<div class="inline-actions playlist-actions"><button class="primary-button" id="new-playlist">${icon('plus')} 플레이리스트 만들기</button><button class="small-button" data-order-collections>목록 순서 편집</button><a class="text-link" href="#collections">다른 사람의 플레이리스트 찾기 →</a></div><div class="explorer-toolbar"><input id="library-search" aria-label="내 플레이리스트 검색" placeholder="내 보관함에서 검색" value="${esc(collectionSearch)}"><select id="library-filter" aria-label="플레이리스트 종류">${[['all','전체 목록'],['mine','내가 만든 목록'],['saved','저장한 공개 목록']].map(([k,v])=>`<option value="${k}" ${collectionFilter===k?'selected':''}>${v}</option>`).join('')}</select><select id="library-sort" aria-label="내 플레이리스트 정렬">${[['custom','내 순서'],['name','이름순'],['recent','최신순']].map(([k,v])=>`<option value="${k}" ${collectionSort===k?'selected':''}>${v}</option>`).join('')}</select></div><div id="library-collections">${filteredCollections()}</div>`;
  else if(tab==='artists'||tab==='producers')html+=identityCards(library.follows.filter(f=>f.kind===(tab==='artists'?'artist':'producer')).map(f=>({...f,id:f.target_id})),tab==='artists'?'artist':'producer');
  else html+=`<div class="inline-actions playlist-actions"><button class="primary-button" data-organize-likes ${library.likes.length?'':'disabled'}>선택해서 플레이리스트 만들기 ${icon('plus')}</button></div>`+list(library.likes);
  return {html,tracks:tab==='likes'?library.likes:[]};
 }
 if(base==='playlist'){
  const d=await api('/api/playlists/'+param),p=d.playlist,owned=me?.id===p.user_id;
  if(p.locked&&owned)return {html:lockedPlaylistHTML(p),tracks:[],playlist:p};
  return {html:`<a class="text-link" href="#${owned||p.saved?'library/playlists':'collections'}">← ${owned||p.saved?'내 보관함':'공개 플레이리스트'}</a><section class="collection-hero">${playlistArt(p)}<div><span class="eyebrow">${p.is_public?'PUBLIC PLAYLIST':'PRIVATE PLAYLIST'}</span><h1>${esc(p.name)}</h1><p class="collection-description">${esc(p.description||'좋아하는 음악을 모아 나누는 나만의 선곡')}</p><p class="field-help">${esc(p.owner_name)} · ${d.tracks.length}곡 · ${time(p.duration)}${p.is_public?' · '+number(p.saves)+'명 저장':''}</p><div class="inline-actions playlist-actions"><button class="primary-button" data-play-all ${d.tracks.length?'':'disabled'}>전체 재생 ${icon('play')}</button>${owned?`<button class="small-button" data-pick-playlist="${p.id}">곡 추가</button><button class="small-button" data-order-playlist="${p.id}">곡 순서 편집</button><button class="small-button" data-edit-playlist="${p.id}">이름 · 소개 · 공개 설정</button><button class="text-link" data-delete-playlist="${p.id}">삭제</button>`:`<button class="small-button ${p.saved?'is-active':''}" data-save-collection="${p.id}" data-saved="${!!p.saved}">${p.saved?'보관함 저장됨 · 해제':'내 보관함에 저장'}</button>`}${p.is_public?'<button class="small-button" data-share>링크 복사</button>':''}</div></div></section><div class="explorer-toolbar"><input id="playlist-filter" aria-label="플레이리스트 안에서 곡 검색" placeholder="이 플레이리스트에서 곡 검색"></div><div id="playlist-song-list">${list(d.tracks,owned?p.id:null)}</div>`,tracks:d.tracks,playlist:p};
 }
 return null;
}
function filteredCollections(){const items=(library.collections||library.playlists).filter(p=>(collectionFilter==='all'||(collectionFilter==='mine')===(p.user_id===me.id))&&(p.name+' '+p.description+' '+p.owner_name).toLowerCase().includes(collectionSearch.toLowerCase()));if(collectionSort==='name')items.sort((a,b)=>b.pinned-a.pinned||a.name.localeCompare(b.name,'ko'));if(collectionSort==='recent')items.sort((a,b)=>b.pinned-a.pinned||b.created-a.created);return collectionGrid(items,'조건에 맞는 플레이리스트가 없어요.');}
function bindExplorer(view){
 if($('#collection-search')){const form=$('#collection-search');form.onsubmit=e=>{e.preventDefault();location.hash='collections?'+new URLSearchParams(new FormData(form));};form.elements.sort.onchange=()=>form.requestSubmit();}
 for(const [id,key] of [['library-search','search'],['library-filter','filter'],['library-sort','sort']]){const el=$('#'+id);if(el)el.oninput=()=>{if(key==='search')collectionSearch=el.value;else if(key==='filter')collectionFilter=el.value;else collectionSort=el.value;$('#library-collections').innerHTML=filteredCollections();};}
 if($('#playlist-filter'))$('#playlist-filter').oninput=e=>{const q=e.target.value.toLowerCase(),items=routeTracks.filter(t=>(t.title+' '+t.artist+' '+t.producer).toLowerCase().includes(q));$('#playlist-song-list').innerHTML=items.length?list(items,view?.playlist?.user_id===me?.id?view.playlist.id:null):'<p class="empty-inline">이 목록에 일치하는 곡이 없어요.</p>';};
}
async function orderCollections(){if(!me)return askLogin();await refreshLibrary();let items=[...library.collections];if(items.length<2)return toast('두 개 이상의 목록을 모으면 순서를 편집할 수 있어요.');dialog(`<h2>플레이리스트 목록 순서</h2><p>고정한 목록이 먼저 표시되고, 그 안에서는 저장한 순서를 따릅니다.</p><form id="collections-order"><div class="playlist-order-rows" id="collections-order-rows"></div><button class="primary-button">목록 순서 저장</button><p class="form-error" role="alert"></p></form>`);const root=$('#collections-order-rows'),paint=()=>root.innerHTML=items.map((p,i)=>`<div class="playlist-order-row"><span>${i+1}</span><div><strong>${esc(p.name)}</strong><small>${p.pinned?'고정한 목록':'일반 목록'}</small></div><button type="button" class="small-button" data-collection-move="${i}" data-dir="-1" aria-label="${esc(p.name)} 위로" ${i===0?'disabled':''}>↑</button><button type="button" class="small-button" data-collection-move="${i}" data-dir="1" aria-label="${esc(p.name)} 아래로" ${i===items.length-1?'disabled':''}>↓</button></div>`).join('');paint();root.onclick=e=>{const b=e.target.closest('[data-collection-move]');if(!b||b.disabled)return;items=AifectQueue.moveTrack(items,Number(b.dataset.collectionMove),Number(b.dataset.dir));paint();};const form=$('#collections-order');form.onsubmit=busyForm(form,async()=>{await api('/api/library/playlists/order','PUT',{playlist_ids:items.map(p=>p.id)});$('#dialog').close();collectionSort='custom';await render();toast('보관함의 목록 순서를 저장했습니다.');});}

async function trackPicker(pid){
 if(!me)return askLogin();const d=await api('/api/playlists/'+pid);await refreshLibrary();const members=new Set(d.tracks.map(t=>t.id)),chosen=new Map();let items=library.likes,token=0;
 dialog(`<h2>플레이리스트에 곡 추가</h2><p>${esc(d.playlist.name)}에 담을 곡을 선택하세요.</p><div class="tabs"><button type="button" class="tab active" data-picker-source="likes">좋아요</button><button type="button" class="tab" data-picker-source="history">최근 들은 곡</button><button type="button" class="tab" data-picker-source="search">검색</button></div><form id="picker-search" class="explorer-toolbar" hidden><input name="q" aria-label="추가할 곡 검색" placeholder="곡이나 아티스트 검색" maxlength="100"><button class="small-button">검색</button></form><form id="picker-add"><div class="likes-track-picker" id="picker-tracks"></div><button class="primary-button" id="picker-submit">선택한 곡 담기 (0)</button><p class="form-error" role="alert"></p></form>`);
 const root=$('#picker-tracks'),paint=()=>{root.innerHTML=items.length?items.map(t=>`<label class="likes-pick-row"><input type="checkbox" value="${t.id}" ${members.has(t.id)?'disabled':chosen.has(t.id)?'checked':''}>${cover(t,'mini-cover')}<span><strong>${esc(t.title)}</strong><small>${esc(t.artist)}${members.has(t.id)?' · 이미 담긴 곡':''}</small></span></label>`).join(''):'<p class="empty-inline">선택할 곡이 없어요. 검색에서 음악을 찾아보세요.</p>';};paint();
 root.onchange=e=>{const input=e.target.closest('input');if(!input)return;const t=items.find(t=>t.id===input.value);if(input.checked)chosen.set(t.id,t);else chosen.delete(input.value);$('#picker-submit').textContent=`선택한 곡 담기 (${chosen.size})`;};
 const select=async(source,q='')=>{const n=++token;try{const data=source==='likes'?{tracks:library.likes}:await api(source==='history'?'/api/history':'/api/search?q='+encodeURIComponent(q));if(n!==token||!root.isConnected)return;items=data.tracks;paint();}catch(e){if(root.isConnected)root.innerHTML=`<p class="form-error">${esc(e.message)}</p>`;}};
 document.querySelectorAll('[data-picker-source]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-picker-source]').forEach(x=>x.classList.toggle('active',x===b));$('#picker-search').hidden=b.dataset.pickerSource!=='search';select(b.dataset.pickerSource);});$('#picker-search').onsubmit=e=>{e.preventDefault();select('search',new FormData(e.target).get('q'));};
 const form=$('#picker-add');form.onsubmit=busyForm(form,async()=>{if(!chosen.size)throw Error('담을 곡을 선택해주세요.');for(const tid of chosen.keys()){await api(`/api/playlists/${pid}/tracks/${tid}`,'PUT');members.add(tid);chosen.delete(tid);}$('#dialog').close();await render();toast('선택한 곡을 플레이리스트에 담았습니다.');});
}

function saveQueue(){try{sessionStorage.setItem('aifect-queue',JSON.stringify({ids:queue,tracks:queue.map(id=>({id,title:trackMap.get(id)?.title,artist:trackMap.get(id)?.artist}))}));}catch{}}
function trackMenu(tid){const t=trackMap.get(tid);if(!t)return;dialog(`<h2>${esc(t.title)}</h2><p>${esc(t.artist)}</p><div class="dialog-list"><button class="small-button" data-play="${tid}">지금 재생</button><button class="small-button" data-queue-insert="${tid}" data-placement="next">다음에 재생</button><button class="small-button" data-queue-insert="${tid}" data-placement="last">재생목록 맨 뒤에 추가</button><button class="small-button" data-add="${tid}">플레이리스트에 저장</button><button class="small-button" data-like="${tid}" aria-pressed="${liked(tid)}">${liked(tid)?'좋아요 해제':'좋아요'}</button><a class="small-button" href="#song/${tid}" data-close-dialog>곡 정보 · 가사 · 댓글</a></div>`);}
function queueDialog(){
 dialog(`<h2>현재 재생목록</h2><p>지금 듣는 순서만 바뀌며, 저장한 플레이리스트에는 영향을 주지 않아요.</p><div class="inline-actions playlist-actions"><button class="small-button" data-player-action="shuffle">${shuffle?'셔플 켜짐':'셔플 끔'}</button><button class="small-button" data-player-action="repeat">${['반복 끔','전체 반복','한 곡 반복'][repeatMode]}</button><button class="text-link" data-clear-queue>대기곡 비우기</button></div><div id="editable-queue" class="playlist-order-rows">${queue.length?queue.map((tid,i)=>{const t=trackMap.get(tid);return `<div class="queue-edit-row"><button class="text-link queue-title" data-queue-play="${tid}"><strong>${esc(t?.title||'음악')}</strong><small>${tid===current?.id?'현재 재생 중':esc(t?.artist||'')}</small></button><button class="small-button" data-move-queue="${i}" data-dir="-1" aria-label="${esc(t?.title)} 재생목록 위로" ${i===0?'disabled':''}>↑</button><button class="small-button" data-move-queue="${i}" data-dir="1" aria-label="${esc(t?.title)} 재생목록 아래로" ${i===queue.length-1?'disabled':''}>↓</button>${tid!==current?.id?`<button class="icon-button" data-remove-queue="${tid}" aria-label="${esc(t?.title)} 대기곡 제거">×</button>`:'<span aria-label="재생 중">▶</span>'}</div>`;}).join(''):'<p class="empty-inline">곡의 더보기에서 ‘다음에 재생’을 선택해보세요.</p>'}</div>`);
}
function moodFieldHTML(tags=''){return `<fieldset class="mood-fields"><legend>이 음악은 언제 들으면 좋을까요?</legend><p class="field-help">선택한 분위기는 발견 화면에서 음악을 찾는 데 사용됩니다.</p><div class="mood-checks">${moodOptions.map(([id,label])=>`<label><input type="checkbox" data-mood-tag="${label}" ${tags.split(',').map(t=>t.trim()).includes(label)?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>`;}
function bindMoodFields(){const input=document.querySelector('input[name="tags"]');if(!input)return;const field=document.createElement('div');field.innerHTML=moodFieldHTML(input.value);input.closest('label').after(field);field.onchange=()=>{const labels=moodOptions.map(x=>x[1]),other=input.value.split(',').map(t=>t.trim()).filter(t=>t&&!labels.includes(t)),chosen=[...field.querySelectorAll('input:checked')].map(x=>x.dataset.moodTag);input.value=[...other,...chosen].join(', ');};input.addEventListener('input',()=>field.querySelectorAll('input').forEach(c=>c.checked=input.value.split(',').map(t=>t.trim()).includes(c.dataset.moodTag)));}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b||b.disabled)return;try{
 if(b.dataset.saveCollection){if(!me)return askLogin();const saved=b.dataset.saved==='true';b.disabled=true;await api(`/api/playlists/${b.dataset.saveCollection}/save`,saved?'DELETE':'PUT');await refreshLibrary();if(location.hash.startsWith('#playlist/'))await render();else{b.dataset.saved=String(!saved);b.textContent=saved?'보관함 저장':'보관함 저장됨';}toast(saved?'보관함에서 저장을 해제했습니다.':'공개 플레이리스트를 내 보관함에 저장했습니다.');}
 else if(b.dataset.pinCollection){b.disabled=true;await api('/api/library/playlists/'+b.dataset.pinCollection,'PATCH',{pinned:b.dataset.pinned!=='true'});await render();}
 else if(b.hasAttribute('data-order-collections'))await orderCollections();
 else if(b.dataset.trackMenu)trackMenu(b.dataset.trackMenu);
 else if(b.dataset.queuePlay){$('#dialog').close();await play(b.dataset.queuePlay);}
 else if(b.dataset.queueInsert){if(b.dataset.queueInsert===current?.id)return toast('지금 재생 중인 곡입니다.');if(queue.length>=500)return toast('현재 재생목록에는 최대 500곡까지 담을 수 있어요.');queue=AifectQueue.insertTrack(queue,b.dataset.queueInsert,current?.id,b.dataset.placement);saveQueue();$('#dialog').close();toast(b.dataset.placement==='next'?'다음에 재생할 곡으로 담았습니다.':'재생목록 맨 뒤에 담았습니다.');}
 else if(b.hasAttribute('data-move-queue')){queue=AifectQueue.moveTrack(queue,Number(b.dataset.moveQueue),Number(b.dataset.dir));saveQueue();queueDialog();}
 else if(b.dataset.removeQueue){queue=AifectQueue.removeTrack(queue,b.dataset.removeQueue,current?.id);saveQueue();queueDialog();}
 else if(b.hasAttribute('data-clear-queue')){queue=AifectQueue.clearWaiting(current?.id);saveQueue();queueDialog();}
 else if(b.hasAttribute('data-close-dialog'))$('#dialog').close();
 }catch(err){toast(err.message);}finally{b.disabled=false;}});

try{const restored=AifectQueue.restoreQueue(sessionStorage.getItem('aifect-queue'));queue=restored.ids;remember(restored.tracks);}catch{}
